<?php
// Test the complete idle message formatting flow

function testIdleMessageFormatting() {
    // Simulate the activityText that would be generated by getIdleReasonFromCallback
    $activityText = 'Простой (Ожидание допоставки (Дефицит по спецификации))';
    
    // Simulate the idle activity handling in TabelEntry->createTabelMessage
    $fio = 'Иванов Иван Иванович';
    $date = '29.09.2025';
    $projectCode = 'ОИ726';
    
    $message = sprintf(
        "<b>%s</b>\r\n😨 ⚠️ %s, Проект <b>%s</b>: ИНЦИДЕНТ - Добавлена запись в табель: <b>⚠️ %s</b>",
        $fio,
        $date,
        $projectCode,
        $activityText
    );
    
    echo "Generated message:\n" . $message . "\n\n";
    
    // Expected format from user's example
    $expected = "<b>Иванов Иван Иванович</b>\r\n😨 ⚠️ 29.09.2025, Проект <b>ОИ726</b>: ИНЦИДЕНТ - Добавлена запись в табель: <b>⚠️ Простой (Ожидание допоставки (Дефицит по спецификации))</b>";
    
    echo "Expected message:\n" . $expected . "\n\n";
    
    // Clean up line endings for comparison
    $messageClean = str_replace("\r\n", "\n", $message);
    $expectedClean = str_replace("\r\n", "\n", $expected);
    
    echo "Match: " . ($messageClean === $expectedClean ? 'YES' : 'NO') . "\n";
}

testIdleMessageFormatting();